mapper.select:
SELECT COALESCE(SUM(points_amount), 0)
FROM points_transaction
WHERE member_id = #{memberId}
  AND source = #{source}
  AND transaction_type = 'EARN'
  AND created_at >= #{startOfMonth}
  AND created_at < #{endOfMonth}

SELECT COALESCE(SUM(points_amount), 0)
FROM points_transaction
WHERE member_id = #{memberId}
  AND transaction_type = 'EARN'
  AND created_at >= #{since}
